<script lang="ts">
  import * as Collapsible from "$lib/components/ui/collapsible";
  import { ChevronRight } from "lucide-svelte";
  import { fade } from "svelte/transition";
  import type { Snippet } from "svelte";

  interface $$Props {
    open?: boolean;
    buttonLabel?: string;
    buttonSnippet?: Snippet;
    children: Snippet;
  }

  let { open = $bindable(false), ...props}: $$Props = $props();

</script>

<Collapsible.Root bind:open={open}>
  <Collapsible.Trigger data-state={open ? 'open' : 'closed'} class="group/collapsible">
    <ChevronRight
      class="ml-auto transition-transform group-data-[state=open]/collapsible:rotate-90 inline-block"
    />
    {#if props.buttonSnippet}
      {@render props.buttonSnippet()}
    {:else}
      {props.buttonLabel}
    {/if}
  </Collapsible.Trigger>
  <Collapsible.Content>
    {#if open}
      <div transition:fade>
        {@render props.children()}
      </div>
    {/if}
  </Collapsible.Content>
</Collapsible.Root>

