import type { JsonSchemaParts, SchemaPartsFnOfType } from './jsonSchemaTypes';
import { ensurePath } from '$lib/blocks/data-utils/ensurePath';
import { getGridNodeOptions } from '$lib/components/composites/dynamic-layout/gridUtils';
import { isPromise } from 'rxjs/internal/util/isPromise';
import type { DynamicLayoutNode } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
import type { Writeable } from "$lib/blocks/utils/ts-magic";

export const hasStyleSchema = () => {
	return {
		dataTab: 'style',
		schemaId: 'style',
		schemaProperties: {
			customStyle: {
				type: 'string',
				title: 'Custom CSS'
			}
		},
		uiSchemaProperties: {
			customStyle: {
				'ui:widget': 'textarea',
				'ui:options': {
					input: {
						autocomplete: 'off',
						rows: 5
					}
				}
			}
		},
		requiredProperties: [],
		getFormValuesByNode: (node: DynamicLayoutNode) => {
			// iterate over properties to get the style object

			let customStyle = node.layoutData?.elementProps?.styleCss ?? '';

			return { customStyle };
		},
		setToNode: (node: DynamicLayoutNode, values: any) => {
			ensurePath(node, 'layoutData.elementProps');

			node.layoutData.elementProps.styleCss = values.customStyle;
		}
	} satisfies JsonSchemaParts;
};

export const hasGridProps = () => {
	return {
		dataTab: 'grid',
		schemaId: 'grid',
		schemaProperties: {
			col: {
				type: 'number',
				title: 'Col'
			},
			row: {
				type: 'number',
				title: 'Row'
			},
			colSpan: {
				type: 'number',
				title: 'Col Span'
			},
			rowSpan: {
				type: 'number',
				title: 'Row Span'
			}

			/*
      cellStyle: {
        type: "string",
        title: "Cell Style (CSS)"
      }*/
		},
		uiSchemaProperties: {
			cellStyle: {
				'ui:widget': 'textarea',
				'ui:options': {
					input: {
						autocomplete: 'off',
						rows: 5
					}
				}
			}
		},
		requiredProperties: [],
		getFormValuesByNode: (node: DynamicLayoutNode) => {
			const gridOptions = getGridNodeOptions(node);

			return {
				col: gridOptions.col,
				row: gridOptions.row,
				colSpan: gridOptions.colSpan,
				rowSpan: gridOptions.rowSpan,
				// cellStyle: gridOptions.cellStyle
			};
		},
		setToNode: (node: DynamicLayoutNode, values: any) => {
			ensurePath(node, 'layoutData.forParent.grid');

			const gridConfig =  node.layoutData.forParent?.grid as Writeable<typeof node.layoutData.forParent.grid>;
			gridConfig.col = values.col;
			gridConfig.row = values.row;
			gridConfig.colSpan = values.colSpan;
			gridConfig.rowSpan = values.rowSpan;
			// gridConfig.cellStyle = values.cellStyle;
		}
	} satisfies JsonSchemaParts;
};

export const hasOrderSchema = () => {
	return {
		dataTab: 'general',
		schemaId: 'order',
		schemaProperties: {
			order: {
				type: 'number',
				title: 'Order'
			}
		},
		uiSchemaProperties: {},
		requiredProperties: [],
		getFormValuesByNode: (node: DynamicLayoutNode) => {
			return {
				order: node.order ?? 0
			};
		},
		setToNode: (node: DynamicLayoutNode, values: any) => {
			node.order = values.order;

			//console.info('set to node')
		}
	} satisfies JsonSchemaParts;
};

export async function mapSchemaPartsToComponents(schemaParts: SchemaPartsFnOfType) {
	const mappedSchemaParts: JsonSchemaParts[] = [];

	for (const schemaPart of schemaParts) {
		const result = schemaPart();

		if (isPromise(result)) {
			mappedSchemaParts.push(await result);
		} else {
			mappedSchemaParts.push(result);
		}
	}

	return mappedSchemaParts;
}
