import type { NodeQueryEntry } from '$lib/database/evolu/queries';
import { LayoutData } from '$lib/database/evolu/datastructure';
import type { ConstructorOf, DeeplyWritable, Writeable } from "$lib/blocks/utils/ts-magic";
import type { SchemaPartsGenerator } from "$lib/components/dashboard-nodes/jsonSchemaTypes";
import type { SvelteComponent } from "svelte";
import type { IconProps } from "lucide-svelte/icons";


// TODO cleanup imports, maybe extract more into other subfolders

export type ChildrenViewModeTypes = 'rows' | 'columns' | 'grid' | 'custom';

export type ChildrenViewMode = {
	type: ChildrenViewModeTypes;
	panelStyle?: string;
	itemStyle?: string;
};

export interface DashboardLayoutNode extends Omit<NodeQueryEntry, 'layoutData' | 'nodeConfig'> {
	layoutData:  DeeplyWritable<typeof LayoutData.Input>;

	// each node has their own config props, which we dont know here
	nodeConfig: any;
	children?: DashboardLayoutNode[];
}

// Just so that it can be used inside the DynamicLayout Components
export interface DynamicLayoutNode extends DashboardLayoutNode {}

export interface DynamicLayoutNodeInfo {
	nodeGroup?: 'LAYOUT' | 'NODE' | 'FUN';
	nodeType: string;
	schemaParts: SchemaPartsGenerator;
	iconComponent?: ConstructorOf<SvelteComponent<IconProps>>;
}

export function getLabel(node: DynamicLayoutNode, allowTypeAsFallback = false) {
	return node.layoutData.label ?? (allowTypeAsFallback ? node.type : '');
}

export function setLabel(node: DynamicLayoutNode, str: string) {
	node.layoutData.label = str;
}
