import type { JsonSchemaParts } from '../jsonSchemaTypes';
import { dependableEnumProperty } from '$lib/blocks/svelte-jsonschema-form/schema-utils';
import { DataSourceRepository } from '$lib/database/dataSourceRepository.svelte.js';
import { ensurePath } from "$lib/blocks/data-utils/ensurePath";
import type { DynamicLayoutNode } from '$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types';

export interface DynamicNodeProps {
	dynamicSourceMode: 'payloadFields' | 'globalDataSource';
	globalDataSource: string;
	payloadFields: {
		label: string;
		type: string;
	}[];
	layout: {
		id: string;
		type: string;
	};
	dynamicData: any[];
}

export async function hasDynamicPayloadFields(): Promise<JsonSchemaParts> {
	const dynamicSourceMode = dependableEnumProperty(
		{
			type: {
				type: 'string',
				enum: ['payloadFields', 'globalDataSource'],
				title: 'Dynamic Source Mode'
			}
		},
		{
			payloadFields: {
				payloadFields: {
					type: 'array',
					title: 'Payload Fields',
					items: {
						type: 'object',
						title: '',
						properties: {
							label: {
								type: 'string',
								title: 'Label'
							},
							type: {
								type: 'string',
								title: 'Type',
								default: 'string'
							}
						}
					}
				}
			},
			globalDataSource: {
				globalDataSource: {
					type: 'string',
					enum: (await DataSourceRepository.getAllSourcesAsync()).map((ds) => ds.config.short),
					title: 'Dynamic Source Mode'
				}
			}
		}
	);

	return {
		dataTab: 'dynamic',
		schemaProperties: {
			dynamicSourceMode: {
				type: 'object',
				title: 'Dynamic Source Mode',
				properties: {
					...dynamicSourceMode.property
				},
				dependencies: {
					...dynamicSourceMode.dependencyEntry
				}
			}
		},
		uiSchemaProperties: {
			dynamicSourceMode: {
				payloadFields: {
					items: {
						type: {
							'ui:field': 'hidden'
						}
					}
				}
			}
		},
		requiredProperties: ['dynamicSourceMode'],
		getFormValuesByNode: (node: DynamicLayoutNode) => {
			const nodeProps = node.nodeConfig as DynamicNodeProps;
			return {
				dynamicSourceMode: {
					type: nodeProps.dynamicSourceMode,
					payloadFields: nodeProps.payloadFields,
					globalDataSource: nodeProps.globalDataSource
				}
			};
		},
		setToNode: (node: DynamicLayoutNode, values: any) => {
			node.nodeConfig.dynamicSourceMode = values.dynamicSourceMode.type;
			node.nodeConfig.globalDataSource = values.dynamicSourceMode.globalDataSource;
			node.nodeConfig.payloadFields = values.dynamicSourceMode.payloadFields;
		}
	};
}

export const hasDynamicData = (currentEntry: DynamicNodeProps) => (): JsonSchemaParts => {
	return {
		dataTab: 'dynamic',
		schemaProperties: {
			dynamicData: {
				type: 'array',
				title: '',
				items: {
					type: 'object',
					properties: currentEntry.payloadFields.reduce(
						(acc, field) => {
							acc[field.label] = {
								type: field.type,
								title: field.label
							};
							return acc;
						},
						{} as Record<string, any>
					)
				}
			}
		},
		uiSchemaProperties: {
			dynamicData: {
				'ui:options': {
					title: ''
				},
				items: {
					'ui:options': {
						title: 'Template Data Entry'
					},
					type: {
						'ui:field': 'hidden'
					}
				}
			}
		},
		requiredProperties: ['dynamicData'],
		getFormValuesByNode: (node: DynamicLayoutNode) => {
			const nodeProps = node.nodeConfig as DynamicNodeProps;
			return {
				dynamicData: nodeProps.dynamicData
			};
		},
		setToNode: (node: DynamicLayoutNode, values: any) => {
			node.nodeConfig.dynamicData = values.dynamicData;
		}
	};
};

export const hasDynamicTypeSchema = (typeList: string[]) => () => {

	const dynamicNodeType = dependableEnumProperty(
		{
			nodeType: {
				type: 'string',
				title: 'Node Type',
				enum: typeList
			}
		},
		{
			children:  {
			},
			collapsible: {
				  "helpText": {
          title: "",
          "description": "Trying to get the Links favicon. If it doesn't work, it will show a globe icon.2",
          "type": "null"
        }
			}
		}
	);

	return {
		dataTab: 'dynamic',
		schemaProperties: dynamicNodeType.property,
		schemaDeps: dynamicNodeType.dependencyEntry,
		uiSchemaProperties: {

		},
		requiredProperties: ['nodeType'],
		getFormValuesByNode: (node: DynamicLayoutNode) => {
			const nodeProps = node.nodeConfig as DynamicNodeProps;

			const combined = {
				nodeType: nodeProps?.layout?.type,
			};

			return combined;
		},
		setToNode: (node: DynamicLayoutNode, values: any) => {
			ensurePath(node, 'nodeConfig.layout');

			const nodeProps = node.nodeConfig as DynamicNodeProps;

			// Check types / add missing props / children for tabs or something
			nodeProps.layout.type = values.nodeType;
		}
	} satisfies JsonSchemaParts;
};
