import jsonata from 'jsonata';
import hash from 'object-hash';


const PlaceholderRegex = /{{([^{}]*(?:{[^{}]*}[^{}]*)*)}}/g;

// return a placeholder path from a string
export function getPlaceholderPathFromString(str: string) {
	const matchedEntries = [...str.matchAll(PlaceholderRegex).map((match) => match[1].trim())];

	return matchedEntries;
}

// go through an object recursively and return all the plaeholder paths from it
export function getPlaceholderPathsFromObject(rootObj: any) {
	const paths = new Set<string>();

	function traverse(obj: any) {
		for (const key in obj) {
			const keyValue = obj[key];
			const typeOfKeyValue = typeof keyValue;
			if (typeOfKeyValue === 'object') {
				if (Array.isArray(keyValue)) {
					for (let item of keyValue) {
						traverse(item);
					}
				} else {
					traverse(keyValue);
				}
			} else {
				if (typeOfKeyValue === 'string' && obj[key].includes('{{')) {
					const results = getPlaceholderPathFromString(obj[key]);

					for (let result of results) {
						paths.add(result);
					}
				}
			}
		}
	}

	traverse(rootObj);

	return [...paths];
}

// check if json path is in the provided object
function isJsonPathMissingInObject(obj: any, path: string) {
	const pathParts = path.split('.');

	let currentObj = obj;

	for (let part of pathParts) {
		if (currentObj[part]) {
			currentObj = currentObj[part];
		} else {
			return path;
		}
	}

	return undefined;
}

// all json paths in the object
export function areJsonPathsMissingInObject(obj: any, paths: string[]) {
	return paths
		.map((path) => {
			return isJsonPathMissingInObject(obj, path);
		})
		.filter((path): path is NonNullable<string> => !!path);
}

export async function evalByJsonata(expression: string, payload: any) {
	const jsnonataInstance = jsonata(expression);

	jsnonataInstance.registerFunction('hash', (input: string) => {
		return hash(input);
	});

	return await jsnonataInstance.evaluate(payload);
}

export async function evalByJsonataPiped(expression: string, payload: any): Promise<any> {
	const expressions = expression.split('|');
	let result = payload;

	for (let i = 0; i < expressions.length; i++) {
		let expression = expressions[i].trim();

		result = await evalByJsonata(expression, result);
	}

	return result;
}

// replace placeholders in a string
export async function replacePlaceholdersAsync(str: string, payload: any) {
	const matches = [...str.matchAll(PlaceholderRegex)];
	const replacements = await Promise.all(
		matches.map(async (match) => {
			const path = match[1];
			const value = await evalByJsonataPiped(path, payload);

			return { match: match[0], value: typeof value === 'string' ? value : JSON.stringify(value) };
		})
	);

	replacements.forEach(({ match, value }) => {
		str = str.replace(match, value);
	});

	return str;
}

export async function replacePlaceholdersArraysAsync(placeholderPaths: string[], payload: any) {
	const replacements = await Promise.all(
		placeholderPaths.map(async (match) => {
			const path = match;
			const value = await evalByJsonataPiped(path, payload);
			return { match: match, value: typeof value === 'string' ? value : JSON.stringify(value) };
		})
	);

	const result: Record<string, any> = {};

	replacements.forEach(({ match, value }) => {
		result[match] = value;
	});

	return result;
}

export async function replacePlaceholdersRecursivelyAsync<TInput>(
	rootObj: TInput,
	payload: any
): Promise<{
	usedPayloadPaths: string[];
	payloads: Record<string, any>;
	missingPaths: string[];
	result: TInput;
}> {
	const clonedObj = structuredClone(rootObj);
	const paths = getPlaceholderPathsFromObject(clonedObj);
	const missingPaths = areJsonPathsMissingInObject(payload, paths);

	if (missingPaths.length) {
		console.info({
			missingPaths,
			paths,
			payload
		});
		// throw new Error(`Missing paths: ${missingPaths.join(', ')}`);
	}

	async function traverse(obj: any) {
		if (!obj) {
			return;
		}

		for (const [key, keyValue] of Object.entries(obj)) {
			const typeOfKeyValue = typeof keyValue;

			if (typeOfKeyValue === 'object') {
				if (Array.isArray(keyValue)) {
					for (let item of keyValue) {
						await traverse(item);
					}
				} else {
					await traverse(keyValue);
				}
			} else {
				if (typeOfKeyValue === 'string' && obj[key].includes('{{')) {
					obj[key] = await replacePlaceholdersAsync(obj[key], payload);
				}
			}
		}
	}

	await traverse(clonedObj);
	const payloadsMap = await replacePlaceholdersArraysAsync(paths, payload);

	for (let missingPath of missingPaths) {
		payloadsMap[missingPath] = 'MISSING!!!';
	}

	return {
		usedPayloadPaths: paths,
		payloads: payloadsMap,
		missingPaths,
		result: clonedObj
	};
}
