import { context } from '$lib/blocks/utils/context-provider';
import type { DynamicLayoutNode } from '$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types';

export const LocalUiStateHandlerContext = context<LocalUiStateHandler>('UiStateHandlerContext');
const UIState_Prefix = 'UIState';

export class LocalUiStateHandler {
	getStorageKey(node: DynamicLayoutNode, property: string) {
		return `${UIState_Prefix}/${node.layoutData.forParent?.customKey ?? node.id}-${node.type}-${property}`;
	}

	// Todo even simpler with $state, someday
	getPropHandler<T>(node: DynamicLayoutNode, property: string, defaultValue: T) {
		return {
			get: () => this.getState<T>(node, property, defaultValue),
			set: (value: any) => this.setState(node, property, value),
		};
	}

	getState<T>(node: DynamicLayoutNode, property: string, defaultValue: T) {
		const storageKey = this.getStorageKey(node, property);
		return (
			JSON.parse(localStorage.getItem(storageKey) || 'null') ?? defaultValue
		);
	}

	setState(node: DynamicLayoutNode, property: string, value: any) {
		const storageKey = this.getStorageKey(node, property);

		localStorage.setItem(storageKey, JSON.stringify(value));
	}
}
