<script lang="ts">
  import {
    type ComponentProps,
    LayoutContext, sortChildrenByOrder
  } from "$lib/components/composites/dynamic-layout";
  import { NodeRepository } from "$lib/database/nodeRepository.svelte.js";
  import DebugDetails from "$lib/components/composites/debug-details/DebugDetails.svelte";
  import { merge } from "lodash";
  import { convertDbNodeToDynamicLayoutNode } from "$lib/database/layoutDbNodeConverter";
  import type { NodeId } from "$lib/database/evolu/datastructure";
  import type {
    DynamicLayoutNode
  } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import hash from "object-hash";
  import ReplacedNode from "./ReplacedNode.svelte";
  import type { PayloadContext } from "./dynamic_node_types";
  import { DynamicRootContext } from "./DynamicLayoutContexts";

  let {
    layoutContext,
    nodeId,
    payloadContext
  }: ComponentProps & {
    nodeId: string;
    payloadContext: PayloadContext
  } = $props();

  const rootRenderChildNode = layoutContext.render.renderChildNode;

  let node = $state<DynamicLayoutNode|null>(layoutContext.node?.children?.[0] ?? null);

  NodeRepository.getNodeAsync(nodeId as NodeId).then((_node) => {
    if (_node) {
      node = convertDbNodeToDynamicLayoutNode(_node);
    }
  });

  let dbChildren = NodeRepository.getNodesState(nodeId as NodeId);
  let childrenOfTemplate = $derived.by(() => {
    if (node?.children) {
      return node.children;
    }

    return dbChildren.rows.map(convertDbNodeToDynamicLayoutNode);
  });
  let childrenIdList = $derived(childrenOfTemplate.map((node) => node.id));


  /**
   * there are two types of payload objects
   *
   * Scope: this is the object passed down from the parent element to the next
   *        when its a nested template it'll be merged
   *        also this scope payload is used as hash to create a custom ID
   *          needed to render it faster AND used as key to identify node data (like a note node)
   *
   * Extended: (name pending)
   *           this is extending the scope one to additional payloads that are accesing the the parent ones by name
   *           also maybe used to access other node datas by data, since its not part of the node hierarchy this doesn't need
   *           to be used as custom key
   */
  function generateScopePayloadObject (payloadContext: PayloadContext, payload: any) {
    const sourceName = payloadContext.typeOfSource === "NODE_PAYLOAD" ? "nodePayload" : payloadContext.shortName;

    return {
      "scope": {
        val: payload,
        of: {
          [sourceName]: payload
        }
      },
    };
  }

  function mapToNodeChildren (children: DynamicLayoutNode[]) {
    // we map the order of children of template children in a new way so that we can keep it "correct" in the rendered way
    // ^ hard sentence to explain xD
    let lastOrder = 1;

    return payloadContext.entries.flatMap((payload) => {
      return sortChildrenByOrder(children).map((child) => {
        const payloadOfContext = generateScopePayloadObject(payloadContext, payload);
        const parentPayload = layoutContext.sharedAdditionalContext?.payload;

        const mergedPayload = merge({}, parentPayload, payloadOfContext);
        const customId = `${child.id}-${hash(mergedPayload)}`;

        return {
          ...child,
          order: lastOrder++,
          layoutData: {
            ...child.layoutData,
            forParent: {
              group: child.layoutData.forParent?.group ?? null,
              customKey: customId
            },

          },
          nodeConfig: {
            ...child.nodeConfig,
              ___payload: payloadOfContext,
          }
         /* props: {
            ...child.props,
            nodeProps: {
              ...child.props?.nodeProps,
              ___payload: payloadOfContext,
              ___customKey: customId,
              forParent: {
                ...child.props?.nodeProps?.forParent
              }
            }
          }*/
        } satisfies DynamicLayoutNode;
      });
    });
  }


</script>

<DebugDetails category="TemplatedLayout/childrenIdList"
              pairs={{"Children": childrenIdList.join(','), "ContextType": layoutContext.ContextType}}
              entries={[{ "key": "node", value: childrenIdList}]} />

{#snippet renderChildNode (_layoutContext: LayoutContext)}
  <DebugDetails category="TemplatedLayout/renderChildNode"
                pairs={{"ID": _layoutContext.node.id, "Children": childrenIdList.join(','),"Type": _layoutContext.node.type, "ContextType": _layoutContext.ContextType}}
                entries={[{ "key": "node", value: _layoutContext.node}, {"key": "context", value: _layoutContext}]} />

  {#if node?.id === _layoutContext.node.id}
    {@const childrenWithPayloads = mapToNodeChildren( childrenOfTemplate)}

    {@const newLayoutContext = DynamicRootContext.FROM(
      layoutContext,
      {
        ...node,
        children: childrenWithPayloads
      },
      renderChildNode)
    }


    <DebugDetails category="TemplatedLayout/isTemplateChildNode"
                  pairs={{"ID": _layoutContext.node.id,"Type": _layoutContext.node.type, "IS": "Template Child Node","ContextType": _layoutContext.ContextType}}
                  entries={[{ "key": "context", value: newLayoutContext}]}
    />

    <!-- Map all children as direct ones, that way we can get the actual children -->
    {@render rootRenderChildNode(newLayoutContext)}
  {:else if (childrenIdList.includes(_layoutContext.node.id) && node)}
    <ReplacedNode layoutContext={_layoutContext} payloadContext={payloadContext}
                  parentNode={node} newRenderChildNode={renderChildNode} {rootRenderChildNode} />
  {:else}
    {#if _layoutContext.node.children}
      {@render rootRenderChildNode(_layoutContext)}
    {:else}
      {@const childNode = _layoutContext.node}

      {@render rootRenderChildNode(_layoutContext.subNode(childNode))}
    {/if}
  {/if}
{/snippet}

{#if node}
  {@render renderChildNode(layoutContext.subNode(node))}
{/if}
