import type { SchemaPartsFnOfType, SchemaPartsOfType } from "../components/dashboard-nodes/jsonSchemaTypes";

export interface GenericDialogPayload {
  title: string;
  description?: string;

  onSubmit: <T>(payload: T) => void;
}

export interface JsonSchemaDialogPayload extends Omit<GenericDialogPayload, 'onSubmit'> {
  type: 'simple'|'tabbed';

  jsonSchemaParts: SchemaPartsFnOfType;
  dataByParts: (parts: SchemaPartsOfType) => Promise<any>;

  onDelete?: () => void;
  onSubmit: (result: {
    schemaParts: SchemaPartsOfType,
    value: any
  }[]) => void;
}

export interface DataSourceDialogPayload {
  title: string;
  description?: string;

  onSubmit: (dataSource: any) => void;
}

export interface CssClassDialogPayload {
  title: string;
  description?: string;

  onSubmit: (cssClass: any) => void;
}

export let dialogState = $state<{
  showJsonSchemaDialog: JsonSchemaDialogPayload | null;
  showChangeParentDialog: GenericDialogPayload | null;
  showGlobalSettingDialog: GenericDialogPayload | null;
  showDataSourceDialog: DataSourceDialogPayload | null;
  showCssClassDialog: CssClassDialogPayload | null;
  showAddNodeDialog: GenericDialogPayload | null;
}>({
  showJsonSchemaDialog: null,
  showChangeParentDialog: null,
  showGlobalSettingDialog: null,
  showDataSourceDialog: null,
  showCssClassDialog: null,
  showAddNodeDialog: null
});
