import { getChildNodesQuery, type NodeQueryEntry } from "$lib/database/evolu/queries";
import { queryState } from "$lib/database/nodeRepository.svelte.js";
import type { NodeId } from "$lib/database/evolu/datastructure";
import { evolu } from "$lib/database/evolu/evolu_instance";
import type { DynamicLayoutNode } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
import { convertDbNodeToDynamicLayoutNode } from "$lib/database/layoutDbNodeConverter";

// TODO maybe use a "max order count" cache instead or any other need for this children cache
// ^ using less data for that
// ^ or use a local table for that?

export const NodeChildrenCache = new Map<string, DynamicLayoutNode[]>();

export const cachedByParentQueries = new WeakMap<{ id: string }, { readonly rows: Array<NodeQueryEntry> }>();

export function getCachedByParentNodeQuery (nodeId: string) {
  const key = { id: nodeId };

  if (cachedByParentQueries.has(key)) {
    return cachedByParentQueries.get(key)!;
  }

  const newQueryState = queryState(() => getChildNodesQuery({ parentId: nodeId as NodeId }), evolu, {
    useLoadQueryResult: true
  });

  cachedByParentQueries.set(key, newQueryState);

  $effect(() => {
    NodeChildrenCache.set(nodeId, newQueryState.rows.map(convertDbNodeToDynamicLayoutNode));
  });

  return newQueryState;
}


export const cachedByIdQueries = new WeakMap<{ id: string }, { readonly rows: Array<NodeQueryEntry> }>();

export function getCachedByIdNodeQuery (nodeId: string) {
  const key = { id: nodeId };

  if (cachedByIdQueries.has(key)) {
    return cachedByIdQueries.get(key)!;
  }

  const newQueryState = queryState(
    () => getChildNodesQuery({ id: nodeId as NodeId }), evolu, {
    useLoadQueryResult: true
  });

  cachedByIdQueries.set(key, newQueryState);

  return newQueryState;
}
