import type { Schema, UiSchema } from "@sjsf/form";
import type { SchemaPartsOfType } from "./jsonSchemaTypes";
import type { DynamicLayoutNode } from '$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types';

// TODO combined those into one ... maybe? or cache? since the schemas are static

export function createJsonSchemaDialogPayload(schemaParts: SchemaPartsOfType): Schema {
	const baseSchema: Schema = {
		type: 'object',
		properties: {},
		required: []
	};

	for (const schemaPart of schemaParts) {
		Object.assign(baseSchema.properties!, schemaPart.schemaProperties!);

		baseSchema.required?.push(...schemaPart.requiredProperties!);
		baseSchema.dependencies = {
			...baseSchema.dependencies,
			...schemaPart.schemaDeps
		}
	}

	return baseSchema;
}

export function createJsonUiSchemaDialogPayload(schemaParts: SchemaPartsOfType): UiSchema {
	const baseSchema: UiSchema = {};

	for (const schemaPart of schemaParts) {
		Object.assign(baseSchema, schemaPart.uiSchemaProperties);
	}

	return baseSchema;
}

export async function getFormValuesByPayloads(
	schemaParts: SchemaPartsOfType,
	node: DynamicLayoutNode
): Promise<any> {
	const formValues: any = {};

	for (const schemaPart of schemaParts) {
		const schemaPartValues = schemaPart.getFormValuesByNode(node);

		if (schemaPartValues instanceof Promise) {
			Object.assign(formValues, await schemaPartValues);
			continue
		}

		Object.assign(formValues, schemaPartValues);
	}

	return formValues;
}

export function setFormValuesToPayload(
	schemaParts: SchemaPartsOfType,
	node: DynamicLayoutNode,
	formValue: any
): void {
	for (const schemaPart of schemaParts) {
		schemaPart.setToNode(node, formValue);
	}
}
