<script lang="ts" module>
  import type { JsonSchemaParts, SchemaPartsGenerator } from "./jsonSchemaTypes";
  import type {
    DynamicLayoutNode,
    DynamicLayoutNodeInfo
  } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { Clock } from "lucide-svelte";
  import "thy-clock";

  interface AnalogClockNodeProps {
    colors: {
      hourHandColor: string;
      minuteHandColor: string;
      secondHandColor: string;
      backgroundColor: string;
    };
    size: number;
  }

  const hasAnalogClockNodeSchema = (): JsonSchemaParts => {
    return {
      dataTab: "general",
      schemaProperties: {
        colors: {
          type: "object",
          properties: {
            hourHandColor: {
              type: "string",
              title: "Hour Hand Color"
            },
            minuteHandColor: {
              type: "string",
              title: "Minute Hand Color"
            },
            secondHandColor: {
              type: "string",
              title: "Second Hand Color"
            },
            backgroundColor: {
              type: "string",
              title: "Background Color"
            }
          },
          required: ["hourHandColor", "minuteHandColor", "secondHandColor", "backgroundColor"]
        },
        size: {
          type: "number",
          title: "Size",
          default: 200
        }
      },
      requiredProperties: [],
      uiSchemaProperties: {},
      getFormValuesByNode: (node: DynamicLayoutNode) => {
        const nodeProps = node.nodeConfig as AnalogClockNodeProps;
        return {
          colors: {
            hourHandColor: nodeProps?.colors?.hourHandColor ?? "#000000",
            minuteHandColor: nodeProps?.colors?.minuteHandColor ?? "#000000",
            secondHandColor: nodeProps?.colors?.secondHandColor ?? "#FF0000",
            backgroundColor: nodeProps?.colors?.backgroundColor ?? "#FFFFFF"
          },
          size: nodeProps?.size ?? 200
        };
      },
      setToNode: (node: DynamicLayoutNode, values: any) => {
        node.nodeConfig.colors = values.colors;
        node.nodeConfig.size = values.size;
      }
    };
  };

  export const SCHEMA_PARTS: SchemaPartsGenerator = (context) => [
    hasAnalogClockNodeSchema
  ];

  export const AnalogClockNodeInfo: DynamicLayoutNodeInfo = {
    nodeType: "analogClock",
    schemaParts: SCHEMA_PARTS,
    iconComponent: Clock
  };
</script>

<script lang="ts">
  import { onMount } from "svelte";
  import { type ComponentProps } from "$lib/components/composites/dynamic-layout";

  let {
    layoutContext
  }: ComponentProps = $props();

  let node = $derived(layoutContext.node);
  let nodeProps = $derived(node.nodeConfig as AnalogClockNodeProps);

  let colors = $derived(nodeProps?.colors ?? {
    hourHandColor: "#000000",
    minuteHandColor: "#000000",
    secondHandColor: "#FF0000",
    backgroundColor: "#FFFFFF"
  });

  let size = $derived(nodeProps?.size ?? 200);
</script>


<div>
  <thy-clock
    {size}
    second-hand-animation="sweep"
    dial-background-color={colors.backgroundColor}
    second-hand-color={colors.secondHandColor}
    minute-hand-color={colors.minuteHandColor}
    hour-hand-color={colors.hourHandColor}
  ></thy-clock>
</div>
