<script module lang="ts">
  import type { SchemaPartsGenerator } from "./jsonSchemaTypes";
  import { hasVariableNameSchema } from "./shared-schemas/variable-name-schema";
  import type { DynamicLayoutNodeInfo } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { PlusCircle } from "lucide-svelte";

  export const SCHEMA_PARTS: SchemaPartsGenerator = (context) => [
    hasVariableNameSchema
  ];

  export const CounterNodeInfo: DynamicLayoutNodeInfo = {
    nodeType: "counter",
    schemaParts: SCHEMA_PARTS,
    iconComponent: PlusCircle
  };
</script>

<script lang="ts">
  import { type ComponentProps } from "$lib/components/composites/dynamic-layout";
  import { Button } from "$lib/components/ui/button";
  import { Minus, Plus } from "lucide-svelte";
  import { applyNodeData, getNodeData } from "../../contexts/nodeDataPersistence.svelte.js";
  import { link } from "$lib/blocks/svelte-utils/linkState.svelte.js";
  import type { VariableNameNodeProps } from "./shared-schemas/variable-name-schema";
  import { getLiveNodeDataStateForName } from "../../contexts/liveNodeData.context.svelte.js";

  let { layoutContext }: ComponentProps = $props();

  const configNodeData = layoutContext.node.nodeConfig as VariableNameNodeProps;

  const liveDataState = getLiveNodeDataStateForName(configNodeData.variableName, { count: 0 });

  const nodeData = getNodeData<{
    count: number;
  }>(layoutContext, { count: 0 });
  const currentNoteData = link(() => nodeData.data);

  $effect(() => {
    liveDataState.current = currentNoteData.current;
  });

  function increment () {
    currentNoteData.current.count += 1;
    saveCount();
  }

  function decrement () {
    currentNoteData.current.count -= 1;
    saveCount();
  }

  function saveCount () {
    applyNodeData(layoutContext, { count: currentNoteData.current?.count }, nodeData.nodeDataId);
  }
</script>

<div>
  <Button onclick={decrement}>
    <Minus />
  </Button>
  <span>{currentNoteData.current.count}</span>
  <Button onclick={increment}>
    <Plus />
  </Button>
</div>
