import type { Component, Snippet } from 'svelte';
import type { ConstructorOf } from '$lib/blocks/utils/ts-magic';
import type { DynamicLayoutNode } from "../dynamic-layout-app-types/dynamic-layout-types";
import { ensurePath } from "$lib/blocks/data-utils/ensurePath";


export type RenderChildNodeSnippet = Snippet<[LayoutContext]>;
export type RenderChildrenSnippet = Snippet<[LayoutContext]>;
export type GenericRenderChildren = Snippet<
	[LayoutContext, DynamicLayoutNode[], Snippet<[LayoutContext, DynamicLayoutNode]>]
>;

/**
 * Basic component props are passed through to each dynamic component
 *
 * You can use @TLayoutContext as is, or if you extend LayoutContext, you can pass your own context type
 */
export interface ComponentProps<TLayoutContext = LayoutContext> {
	layoutContext: TLayoutContext;
}

export type DynamicLayoutComponents = Record<string, Component<ComponentProps>>;

export class LayoutContext<T = unknown> {
	constructor(
		public readonly nodeInformations: {
			node: DynamicLayoutNode;
			root: DynamicLayoutNode;
			depth: number;
			parent?: DynamicLayoutNode;
		},
		public readonly render: {
			components: DynamicLayoutComponents;
			renderChildNode: RenderChildNodeSnippet;
			renderChildren: RenderChildrenSnippet;
			genericRenderChildren: GenericRenderChildren;
		},
		// this is shared across all the context instances
		public readonly sharedAdditionalContext: T = null as any as T
	) {}

	/* In case you want to have a custom LayoutContext, you can override everything here */

	get node() {
		return this.nodeInformations.node;
	}

	get depth() {
		return this.nodeInformations.depth;
	}

	get components() {
		return this.render.components;
	}

	get parent() {
		return this.nodeInformations.parent;
	}

	protected getConstructor() {
		return this.constructor as ConstructorOf<typeof LayoutContext>;
	}

	getNodeConfig<TNodeConfig>() {
		ensurePath(this.node, 'nodeConfig');

		const nodeProps = this.node.nodeConfig;

		return nodeProps as typeof nodeProps & TNodeConfig;
	}

	subNode(
		_newNode: DynamicLayoutNode,
		overrides?: {
			elementProps?: DynamicLayoutNode['layoutData']['elementProps'];
		}
	) {
		const newNode: DynamicLayoutNode = {
			..._newNode,
			layoutData: {
				..._newNode.layoutData,
				elementProps: {
					..._newNode.layoutData?.elementProps,
					...overrides?.elementProps
				}
			},
		};

		const constructor = this.getConstructor();

		const renderAsAny = this.render as any;

		const instance = new constructor(
			{
				node: newNode,
				root: this.nodeInformations.root,
				depth: this.depth + 1,
				parent: this.node
			},
			renderAsAny,
			this.sharedAdditionalContext
		);

		return instance;
	}

	public get ContextType(): string {
		return this.constructor.name;
	}
}

export function getNodeClassName(layoutContext: LayoutContext, prefix = '', node?: DynamicLayoutNode) {
	node ??= layoutContext.node;

	const chosenClassName =
		layoutContext.nodeInformations.root.type === 'dynamic'
			? `${prefix}_${node.id}_${crypto.randomUUID()}`
			: `${prefix}_${node.id}`;

	return chosenClassName;
}
