// create a custom LayountContext
export const additionalContext = $state({ editMode: false, DEBUG_MODE: false });

syncToState(
	'evolu-edit-mode',
	() => additionalContext,
	(value) => {
		const parsedContext = JSON.parse(value ?? '{}');

		additionalContext.DEBUG_MODE = parsedContext.DEBUG_MODE ?? false;
		additionalContext.editMode = parsedContext.editMode ?? false;
	}
);

const AllowedNodeTypes = $derived(SCHEMA_NODE_TYPES.TYPES_LIST.filter((t) => t !== 'tab'));

export function initializeContexts() {
	EditModeContext.init({
		get inEditMode() {
			return additionalContext.editMode;
		},

		addChildToNode: openAddNewNodeDialog
	});

	NodePersistenceContext.init(NodePersistence);

	ButtonActionHandlerContext.init((actions, context) => {
		const typedContext = context as any as EditModeLayoutContext;

		const isInEditMode = typedContext.sharedAdditionalContext.editMode;

		const showEditDialog = !actions?.length || actions.some((a) => a.type === 'open_url' && !a.url);

		// console.info({ typedContext, actions, isInEditMode, showEditDialog });

		if (
			showEditDialog &&
			!typedContext.sharedAdditionalContext.editMode &&
			typedContext.nodeInformations.root.type === 'dynamic'
		) {
			alert('You need to setup the button actions first!');
			return;
		}

		if (isInEditMode || showEditDialog) {
			openEditNodeDialog(typedContext);
		} else {
			for (const action of actions) {
				switch (action.type) {
					case 'open_url': {
						window.open(action.url, action.target ?? '_blank');
						break;
					}
				}
			}
		}
	});

	LocalUiStateHandlerContext.init(new LocalUiStateHandler());
}

function getComponentSchemas(
	layoutContext: LayoutContext,
	selectedType: string,
	isChildOfGrid: boolean
) {
	const componentSchemas: SchemaPartsFnOfType = [
		...getComponentTypeSchemas(layoutContext, selectedType)
	];

	if (isChildOfGrid) {
		componentSchemas.push(hasGridProps);
	}

	if (nodeCanHoldChildren(layoutContext.nodeInformations.node) && !isChildOfGrid) {
		componentSchemas.push(hasOrderSchema);
	}

	return componentSchemas;
}

export async function openAddNewNodeDialog(layoutContext: LayoutContext) {
	let onlyAllowedType = '';

	const targetNode = convertDbNodeToDynamicLayoutNode(
		await NodeRepository.getNodeAsync(layoutContext.node.id as NodeId)
	);

	if (targetNode.type === 'tabs') {
		onlyAllowedType = 'tab';
	}

	if (onlyAllowedType) {
		openAddNewNodeDialog2(layoutContext, targetNode, onlyAllowedType);
		return;
	}

	dialogState.showAddNodeDialog = {
		title: `Add a new child to ${getLabel(layoutContext.node)}`,
		onSubmit: async (nodeType: string) => {
			openAddNewNodeDialog2(layoutContext, targetNode, nodeType);
		}
	};
}

function findNextFreeOrderBasedOnNodes(nodes: DynamicLayoutNode[]): number {
	const orders = nodes
		.map((node) => node.order)
		.filter((order) => order !== undefined)
		.sort((a, b) => a - b);

	let nextOrder = 1;
	for (const order of orders) {
		if (order !== nextOrder) {
			continue;
		}
		nextOrder++;
	}

	return nextOrder;
}

export async function openAddNewNodeDialog2(
	layoutContext: LayoutContext,
	targetParentNode: DynamicLayoutNode,
	selectedType: string
) {
	const childrenRenderViewMode = getChildrenViewModeProps(targetParentNode);
	const isChildOfGrid = childrenRenderViewMode.type === 'grid';
	const componentSchemas = getComponentSchemas(layoutContext, selectedType, isChildOfGrid);

	const defaultData = {
		label: 'New ' + selectedType,
		nodeType: selectedType,
		order: 1
	};

	const nodeCanHolderChildren = nodeCanHoldChildren(layoutContext.nodeInformations.node);

	const nodesOfTarget = NodeChildrenCache.get(targetParentNode.id) ?? [];
	if (nodeCanHolderChildren && !isChildOfGrid) {
		const nextFreeOrder = findNextFreeOrderBasedOnNodes(nodesOfTarget);

		defaultData.order = nextFreeOrder;
	}

	let defaultGridCellConfig: GridChildNodeOptions = {
		col: 1,
		row: 1,
		colSpan: 1,
		rowSpan: 1
	};

	if (isChildOfGrid) {
		const nodesOfTarget = NodeChildrenCache.get(targetParentNode.id) ?? [];
		const gridEntries = nodesOfTarget.map(getGridNodeOptions);

		const nextFreeCell = findNextFreeCellBasedOnNodes(gridEntries);
		defaultGridCellConfig = {
			col: nextFreeCell.col,
			row: nextFreeCell.row,
			colSpan: nextFreeCell.colSpan,
			rowSpan: nextFreeCell.rowSpan
		};
	}

	const componentSchemaObjects = await mapSchemaPartsToComponents(componentSchemas);

	const isOnlyOneOfUISchemas = componentSchemaObjects.every(
		(s) => !!s.schemaId && ['order', 'grid', 'style'].includes(s.schemaId)
	);

	const dummyNode: Partial<DynamicLayoutNode> = {
		layoutData: {},
		nodeConfig: {}
	};

	if (isOnlyOneOfUISchemas) {
		// @ts-expect-error the dummy doesnt have all props, but not needed
		const result = await getFormValuesByPayloads(componentSchemaObjects, dummyNode);
		const combinedDefaultDataObj = {
			...result,
			label: result.label || defaultData.label,
			order: result.order ?? defaultData.order,
			...defaultGridCellConfig
		};

		await NodePersistence.addNode(
			layoutContext.nodeInformations?.root?.type,
			targetParentNode.id,
			(nodeInState) => {
				ensurePath(nodeInState, 'nodeConfig');
				ensurePath(nodeInState, 'layoutData');

				nodeInState.type = selectedType;

				setFormValuesToPayload(componentSchemaObjects, nodeInState, combinedDefaultDataObj);

				if (nodeInState.type === 'dynamic') {
					const nodeProps = nodeInState.nodeConfig as DynamicNodeProps;
					nodeProps.dynamicData = [];
					nodeProps.payloadFields = [];
				}
			}
		);

		return;
	}

	dialogState.showJsonSchemaDialog = {
		type: 'tabbed',
		title: `Add a new child to ${getLabel(targetParentNode) ?? ` this ${targetParentNode.type}`}`,

		jsonSchemaParts: componentSchemas,
		dataByParts: async (parts) => {
			// @ts-expect-error the dummy doesnt have all props, but not needed
			const result = await getFormValuesByPayloads(parts, dummyNode);

			return {
				...result,
				// using || to ignore empty string or 0
				label: result.label || defaultData.label,
				order: result.order || defaultData.order,
				...defaultGridCellConfig
			};
		},

		onSubmit: async (data) => {
			await NodePersistence.addNode(
				layoutContext.nodeInformations?.root?.type,
				targetParentNode.id,
				(nodeInState) => {
					ensurePath(nodeInState, 'nodeConfig');
					ensurePath(nodeInState, 'layoutData');

					nodeInState.type = selectedType;

					for (const schemaPartInfo of data) {
						setFormValuesToPayload(schemaPartInfo.schemaParts, nodeInState, schemaPartInfo.value);
					}

					if (nodeInState.type === 'dynamic') {
						const nodeProps = nodeInState.nodeConfig as DynamicNodeProps;
						nodeProps.dynamicData = [];
						nodeProps.payloadFields = [];
					}
				}
			);
		}
	};
}

export async function openEditNodeDialog(layoutContext: LayoutContext) {
	const targetNode = layoutContext.node;

	const componentSchemas = [
		...getComponentTypeSchemas(layoutContext, targetNode.type),
		hasStyleSchema
	];

	const nodeInState = convertDbNodeToDynamicLayoutNode(
		await NodeRepository.getNodeAsync(targetNode.id as NodeId)
	);

	if (!nodeInState) {
		alert('could not find the node in the state!');
		return;
	}

	const childrenRenderViewMode = getChildrenViewModeProps(layoutContext.nodeInformations.parent);
	const isChildOfGrid = childrenRenderViewMode.type === 'grid';

	if (isChildOfGrid) {
		componentSchemas.push(hasGridProps);
	}
	if (nodeCanHoldChildren(layoutContext.nodeInformations.parent) && !isChildOfGrid) {
		componentSchemas.push(hasOrderSchema);
	}

	// move to a function inside of each component
	if (targetNode.type === 'tabs' && layoutContext.nodeInformations.root.type !== 'dynamic') {
		componentSchemas.push(canAddChildrenAtRuntime);
	}

	if (componentSchemas.length === 0) {
		alert('no component schema yet!');
		return;
	}

	dialogState.showJsonSchemaDialog = {
		type: 'tabbed',

		title: `Edit ${getLabel(targetNode)}`,
		jsonSchemaParts: componentSchemas,
		dataByParts: async (parts) => {
			// console.info('requesting data for parts', parts);
			const result = await getFormValuesByPayloads(parts, targetNode);
			// console.info('result of data request', result);
			return result;
		},

		onSubmit: async (data) => {
			for (const schemaPartInfo of data) {
				setFormValuesToPayload(schemaPartInfo.schemaParts, nodeInState!, schemaPartInfo.value);
			}

			/*console.info('FormValuesAfter', {
        nodeInState
      });*/

			const { id, nodeConfig, layoutData } = nodeInState!;

			NodeRepository.updateDbNode({
				id,
				nodeConfig,
				layoutData
			});

			if (targetNode.type === 'dynamic') {
				// ensurePath(targetNode, 'props.nodeProps.layout');
				const layoutTmplateNodeConfig = targetNode.nodeConfig as DynamicNodeProps;
				const layoutTmplateNodeId = layoutTmplateNodeConfig.layout?.id;

				const loadedTemplateNode = await NodeRepository.getNodeAsync(layoutTmplateNodeId as NodeId);

				NodeRepository.updateDbNode({
					id: loadedTemplateNode.id,
					type: layoutTmplateNodeConfig.layout?.type ?? 'children'
				});
			}
		},
		onDelete: () => {
			NodePersistence.deleteNode(targetNode.id);
		}
	};
}

export function openChangeParentDialog(layoutContext: LayoutContext) {
	const targetNode = layoutContext.node;

	dialogState.showChangeParentDialog = {
		title: `Change Parent of ${getLabel(targetNode)}`,
		onSubmit: (newParentId: string) => {
			NodePersistence.changeParentNode(layoutContext, targetNode.id, newParentId);
		}
	};
}

