const CACHE_KEY_PREFIX = 'rssCache_';

export function getCachedRSSData(rssUrl: string): { title: string; description: string; imageUrl: string | null }[] | null {
  const cachedData = localStorage.getItem(CACHE_KEY_PREFIX + rssUrl);
  return cachedData ? JSON.parse(cachedData) : null;
}

export function setCachedRSSData(rssUrl: string, data: { title: string; description: string; imageUrl: string | null }[]): void {
  localStorage.setItem(CACHE_KEY_PREFIX + rssUrl, JSON.stringify(data));
}
