import type { JsonSchemaParts } from '../jsonSchemaTypes';
import { ensurePath } from '$lib/blocks/data-utils/ensurePath';
import type { DynamicLayoutNode } from '$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types';

export interface VariableNameNodeProps {
	variableName: string;
}

export function hasVariableNameSchema(): JsonSchemaParts {
	return {
		dataTab: 'general',
		schemaProperties: {
			variableName: {
				type: 'string',
				title: 'Variable Name'
			}
		},
		uiSchemaProperties: {},
		requiredProperties: [],
		getFormValuesByNode: (node: DynamicLayoutNode) => {
			return {
				variableName: node.nodeConfig?.variableName ?? ''
			};
		},
		setToNode: (node: DynamicLayoutNode, values: any) => {
			ensurePath(node, 'nodeConfig');

			node.nodeConfig.variableName = values.variableName;
		}
	};
}
