<script lang="ts" module>
  import type { DynamicLayoutNodeInfo } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { Clock } from "lucide-svelte";

  export const WorkTimeNodeInfo: DynamicLayoutNodeInfo = {
    nodeType: "workTime",
    schemaParts: () => [],
    iconComponent: Clock
  };
</script>

<script lang="ts">
  import { onMount } from 'svelte';
  import { Button } from '$lib/components/ui/button';
  import { type ComponentProps } from '$lib/components/composites/dynamic-layout';
  import { NodePersistenceContext } from '../../contexts/nodePersistence.context';

  let {
    layoutContext
  }: ComponentProps = $props();

  let isRunning = $state(false);
  let time = $state(8 * 60 * 60); // 8 hours in seconds
  let interval;
  let startedTime = $state<number | null>(null);

  const nodePersistenceContext = NodePersistenceContext.get();

  function startTimer() {
    if (!isRunning) {
      isRunning = true;
      startedTime = Date.now();
      saveStartedTime();
      interval = setInterval(() => {
        if (time > 0) {
          time -= 1;
        } else {
          stopTimer();
        }
      }, 1000);
    }
  }

  function stopTimer() {
    if (isRunning) {
      isRunning = false;
      clearInterval(interval);
    }
  }

  function resetTimer() {
    stopTimer();
    time = 8 * 60 * 60; // Reset to 8 hours
    startedTime = null;
    saveStartedTime();
  }

  function pauseTimer() {
    if (isRunning) {
      isRunning = false;
      clearInterval(interval);
    }
  }

  function saveStartedTime() {
    nodePersistenceContext.applyNodeConfig(layoutContext, layoutContext.node.id, (nodeProps) => {
      nodeProps.startedTime = startedTime;
    });
  }

  function loadStartedTime() {
    const nodeProps = layoutContext.getNodeConfig<{ startedTime: number | null }>();
    startedTime = nodeProps.startedTime ?? null;
  }

  onMount(() => {
    loadStartedTime();
    return () => {
      clearInterval(interval);
    };
  });

  function formatTime(seconds: number) {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;
    return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  }
</script>

<div>
  <Button onclick={startTimer} disabled={isRunning}>Start</Button>
  <Button onclick={pauseTimer} disabled={!isRunning}>Pause</Button>
  <Button onclick={resetTimer}>Reset</Button>
  <div>
    <p>Work Time: {formatTime(time)}</p>
    {#if time === 0}
      <p>Work time is over!</p>
    {/if}
  </div>
</div>
