import {
	LayoutContext,
	type RenderChildNodeSnippet
} from '$lib/components/composites/dynamic-layout';
import { merge } from 'lodash';
import type { DynamicLayoutNode } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";

export class DynamicRootContext extends LayoutContext<{ isTemplateNode: boolean }> {
	constructor(
		nodeInformations: LayoutContext['nodeInformations'],
		render: LayoutContext['render'],
		additionalContext: { isTemplateNode: boolean }
	) {
		super(nodeInformations, render, additionalContext);
	}

	static FROM(
		previousContext: LayoutContext,
		newNode: DynamicLayoutNode,
		renderChildNode: RenderChildNodeSnippet
	) {
		const additionalContextProps = {
			isTemplateNode: true,
			...(previousContext.sharedAdditionalContext ?? {})
		};

		const newNodeInformations = {
			...previousContext.nodeInformations,
			node: newNode
		};

		const newRender = {
			...previousContext.render,
			renderChildNode
		};

		return new DynamicRootContext(newNodeInformations, newRender, additionalContextProps);
	}
}

export class DynamicPayloadNodeContext extends LayoutContext<{
	isTemplateNode: boolean;
	payload: Record<string, any>;
}> {
	constructor(
		nodeInformations: LayoutContext['nodeInformations'],
		render: LayoutContext['render'],
		additionalContext: {
			isTemplateNode: boolean;
			payload: Record<string, any>;
		}
	) {
		super(nodeInformations, render, additionalContext);
	}

	static FROM(
		previousContext: LayoutContext,
		rootNode: DynamicLayoutNode,
		newNode: DynamicLayoutNode,
		renderChildNode: RenderChildNodeSnippet,
		payload: Record<string, any>
	) {
		const prevAdditionalContext = (previousContext.sharedAdditionalContext ?? {}) as {
			isTemplateNode: boolean;
			payload: Record<string, any>;
		};

		const additionalContextProps: {
			isTemplateNode: boolean;
			payload: Record<string, any>;
		} = {
			...prevAdditionalContext,
			payload: merge({}, prevAdditionalContext?.payload, payload),
			isTemplateNode: true
		};

		const newNodeInformations = {
			...previousContext.nodeInformations,
			root: rootNode,
			node: newNode
		};

		const newRender = {
			...previousContext.render,
			renderChildNode
		};

		return new DynamicPayloadNodeContext(newNodeInformations, newRender, additionalContextProps);
	}
}
