export function syncToState<TType>(
	storageKey: string,
	subscribe: () => TType,
	set: (value: string | null) => void
) {
	const readFromLS = localStorage.getItem(storageKey);
	set(readFromLS);

	$effect.root(() => {
		$effect(() => {
			const newValue = subscribe();

			localStorage.setItem(storageKey, JSON.stringify(newValue));
		});
	});
}
