
type Split<S extends string, D extends string> = string extends S
	? string[]
	: S extends ''
		? []
		: S extends `${infer T}${D}${infer U}`
			? [T, ...Split<U, D>]
			: [S];

type NestedObject<T extends any[], V> = T extends [infer K, ...infer Rest]
	? K extends string
		? { [P in K]: NestedObject<Rest, V> }
		: never
	: V;

export type ParsePath<S extends string, V> = NestedObject<Split<S, '.'>, V>;

export function ensurePath<TObj extends Record<string, any>, TPath extends string>(
	node: TObj,
	path: TPath
): asserts node is TObj & ParsePath<TPath, Record<string, any>> {
	const pathParts = path.split('.') as string[];

	let current: Record<string, any> = node;

	for (const part of pathParts) {
		current = current[part] ??= {};
	}
}
