<script lang="ts" module>
  import type { SchemaPartsGenerator } from "../jsonSchemaTypes";
  import { hasTitleSchema } from "../shared-schemas/title-schema";
  import { hasNamedChildrenNodes } from "../shared-schemas/children-schemas";
  import type { DynamicLayoutNodeInfo } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { BetweenVerticalStart } from "lucide-svelte";

  export const SCHEMA_PARTS: SchemaPartsGenerator = (context) => [
    hasTitleSchema(false),
    hasNamedChildrenNodes("tab"),
    () => ({
      dataTab: "general",
      schemaProperties: {
        position: {
          type: "string",
          enum: ["top", "right", "bottom", "left"],
          default: "top",
          title: "Tab Position"
        }
      },
      uiSchemaProperties: {},
      requiredProperties: [],
      getFormValuesByNode: (node) => {
        return {
          position: node.nodeConfig?.position ?? "top"
        };
      },
      setToNode: (node, values) => {
        node.nodeConfig.position = values.position;
      }
    })
  ];

  export const TabsNodeInfo: DynamicLayoutNodeInfo = {
    nodeGroup: "LAYOUT",
    nodeType: "tabs",
    schemaParts: SCHEMA_PARTS,
    iconComponent: BetweenVerticalStart
  };
</script>
<script lang="ts">
  import { Tabs, Tab } from "svelte-ux";
  import {
    childrenViewModeItem,
    childrenViewModePanel,
    type ComponentProps, getNodeClassName
  } from "$lib/components/composites/dynamic-layout";
  import type { TabsNodeProps } from "../TabsNodeTypes";
  import { LocalUiStateHandlerContext } from "../../../contexts/uiStateHandler.context";
  import LucideIcon from "$lib/components/composites/lucide-svelte-icons/LucideIcon.svelte";
  import { EditModeContext } from "../../../contexts/editMode.context";
  import type { CanAddChildrenAtRuntimeNodeProps } from "../../../dynamic_layout_test/KnownNodeProps";
  import { NodeRepository } from "$lib/database/nodeRepository.svelte.js";
  import type { NodeId } from "$lib/database/evolu/datastructure";
  import { convertDbNodeToDynamicLayoutNode } from "$lib/database/layoutDbNodeConverter";
  import {
    getLabel
  } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { styleTagString } from "$lib/blocks/html-utils/styleTagString";

  let { layoutContext }: ComponentProps = $props();

  let node = $derived(layoutContext.node);

  let nodeProps = $derived(node.nodeConfig as TabsNodeProps);

  const savedSelectedTabState = LocalUiStateHandlerContext.get().getPropHandler(node, "selectedTab", nodeProps?.selectedTab ?? node.children?.[0].id ?? "");

  let selectedTab = $state(savedSelectedTabState.get());
  let position = $derived(nodeProps?.position ?? "top");

  function setSelectedTab (newSelectedTab: string) {
    selectedTab = newSelectedTab;

    if (nodeProps) {
      nodeProps.selectedTab = newSelectedTab;
    }

    savedSelectedTabState.set(newSelectedTab);
  }

  let dbChildren = NodeRepository.getNodesState(node.id as NodeId);
  let children = $derived(node.children || dbChildren.rows.map(convertDbNodeToDynamicLayoutNode));

  let options = $derived((children).map(subNode => {

    return {
      label: getLabel(subNode),
      value: subNode.id,
      className: getNodeClassName(layoutContext, "tab", subNode),
      subNode: subNode
    };
  }));


  let editModeContext = EditModeContext.get();

  const can = node.nodeConfig as CanAddChildrenAtRuntimeNodeProps;

</script>

{#each options as option (option.value)}
  {@const childrenViewModePanelStyle = childrenViewModeItem(layoutContext.node, option.subNode)}

  {@html styleTagString(option.className, childrenViewModePanelStyle)}
{/each}

<Tabs
  placement={position}
  classes={{
      content: "border px-1 py-1 rounded-b rounded-tr z-10",
      tab: { root: "rounded-t" },
    }}
>
  {#each options as option (option.value)}
    <Tab
      on:click={() => setSelectedTab(option.value)}
      selected={ selectedTab === option.value}
      class={option.className + ' ' + (option.value === selectedTab ? 'selected' : '') }
    >
      {option.label}
    </Tab>
  {/each}

  {#if editModeContext.inEditMode || (can?.addChildrenAtRuntime && layoutContext.nodeInformations.root.type !== "dynamic")}
    <Tab
      on:click={() => editModeContext.addChildToNode(layoutContext)}
    >
      <LucideIcon iconName="Plus" size="20" color="white">

      </LucideIcon>
    </Tab>
  {/if}

  <svelte:fragment slot="content" let:value>
    {@const selectedTabChildNode = children.find(tab => tab.id === selectedTab) }

    {#if selectedTabChildNode}
      {#key selectedTabChildNode.id}
        {@render layoutContext.render.renderChildNode(layoutContext.subNode(selectedTabChildNode))}
      {/key}
    {/if}
  </svelte:fragment>
</Tabs>
