<script lang="ts" module>
  import type { JsonSchemaParts, SchemaPartsGenerator } from "./jsonSchemaTypes";
  import type { DynamicLayoutNodeInfo } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { Globe } from "lucide-svelte";

  export interface IframeNodeProps {
    url: string;
    refreshInterval?: number;
    height?: string;
    width?: string;
  }

  const hasIframeSchema = (): JsonSchemaParts => {
    return {
      dataTab: "general",
      schemaProperties: {
        url: {
          type: "string",
          title: "URL"
        },
        refreshInterval: {
          type: "number",
          title: "Refresh Interval (seconds)",
          default: 0
        },
        height: {
          type: "string",
          title: "Height",
          default: "100%"
        },
        width: {
          type: "string",
          title: "Width",
          default: "100%"
        }
      },
      requiredProperties: ["url"],
      uiSchemaProperties: {},
      getFormValuesByNode: (node) => {
        const nodeProps = node.nodeConfig as IframeNodeProps;
        return {
          url: nodeProps.url,
          refreshInterval: nodeProps.refreshInterval,
          height: nodeProps.height ?? "100%",
          width: nodeProps.width ?? "100%"
        };
      },
      setToNode: (node, values) => {
        node.nodeConfig.url = values.url;
        node.nodeConfig.refreshInterval = values.refreshInterval;
        node.nodeConfig.height = values.height;
        node.nodeConfig.width = values.width;
      }
    };
  };

  export const SCHEMA_PARTS: SchemaPartsGenerator = (context) => [
    hasIframeSchema
  ];

  export const IframeNodeInfo: DynamicLayoutNodeInfo = {
    nodeType: "iframe",
    schemaParts: SCHEMA_PARTS,
    iconComponent: Globe
  };
</script>

<script lang="ts">
  import { type ComponentProps } from "$lib/components/composites/dynamic-layout";

  let {
    layoutContext
  }: ComponentProps = $props();

  let node = $derived(layoutContext.node);
  let nodeProps = $derived(node.nodeConfig as IframeNodeProps);

  let url = $derived(nodeProps.url ?? "");
  let refreshInterval = $derived(nodeProps.refreshInterval);
  let height = $derived(nodeProps.height ?? "100%");
  let width = $derived(nodeProps.width ?? "100%");

  let iframeSrc = $state(url);

  function refreshIframe() {
    iframeSrc = url;
  }

  $effect(() => {
    if (refreshInterval) {
      const intervalId = setInterval(refreshIframe, refreshInterval * 1000);
      return () => clearInterval(intervalId);
    }
  });
</script>

<iframe src={iframeSrc} style={`width: ${width}; height: ${height}; border: none;`}></iframe>
