import { LayoutContext } from '$lib/components/composites/dynamic-layout';
import type {
	InsertableNodeData,
	NodeDataId,
	NodeId,
	UpdatableNodeData,
} from '$lib/database/evolu/datastructure';
import { evolu } from '$lib/database/evolu/evolu_instance';
import { queryState } from '$lib/database/nodeRepository.svelte';
import { getNodeDataByIdPairQuery } from '$lib/database/evolu/queries';

export function getIdPair(layoutContext: LayoutContext) {
	const targetNodeId = layoutContext.nodeInformations.node.id as NodeId;
	const customId = layoutContext.nodeInformations.node.layoutData.forParent?.customKey ?? '';

	return {
		targetNodeId,
		customId
	};
}

export function applyNodeData(
	layoutContext: LayoutContext,
	nodeProps: any,
	nodeDataId?: NodeDataId
) {
	const { targetNodeId, customId } = getIdPair(layoutContext);

	if (nodeDataId) {
		const updateModel: UpdatableNodeData = {
			id: nodeDataId,
			nodeId: targetNodeId,
			subId: customId,
			data: nodeProps
		};

		return evolu.update('nodeData', updateModel);
	} else {
		const insertModel: InsertableNodeData = {
			nodeId: targetNodeId,
			subId: customId,
			data: nodeProps
		};

		return evolu.insert('nodeData', insertModel);
	}
}

export function getNodeData<TData>(
	layoutContext: LayoutContext,
	defaultData: TData
): {
	nodeDataId: NodeDataId;
	data: TData;
} {
	const { targetNodeId, customId } = getIdPair(layoutContext);
	const query = queryState(() => getNodeDataByIdPairQuery(targetNodeId, customId), evolu, {
		useLoadQueryResult: true
	});

	const currentDerived = $derived.by(() => {
		const row = query.rows[0];

		const dataJsonString = row?.data;

		return {
			nodeDataId: row?.id,
			data: dataJsonString ? (JSON.parse(dataJsonString) as TData) : defaultData
		};
	});

	return {
		get nodeDataId() {
			return currentDerived.nodeDataId;
		},
		get data() {
			return currentDerived.data;
		}
	};
}
