export const LiveNodeDataState = $state({} as Record<string, any>);

export function getLiveNodeDataStateForName<T>(name: string, startingValue: T) {
	let state = $state(startingValue);

	$effect(() => {
		if (name !== '' && name !== undefined) {
			LiveNodeDataState[name] = state;
		}
	});

	return {
		get current() {
			return state;
		},
		set current(value: T) {
			state = value;
		}
	};
}
