<script lang="ts" module>
  import type { JsonSchemaParts, SchemaPartsGenerator } from "./jsonSchemaTypes";
  import type { DynamicLayoutNode, DynamicLayoutNodeInfo } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { Clock } from "lucide-svelte";

  interface ClockNodeProps {
    colors: {
      timeColor: string;
      dateColor: string;
      dayColor: string;
      monthColor: string;
    };
    visibility: {
      showTime: boolean;
      showDate: boolean;
      showDay: boolean;
      showMonth: boolean;
    };
  }

  const hasClockNodeSchema = (): JsonSchemaParts => {
    return {
      dataTab: "general",
      schemaProperties: {
        colors: {
          type: "object",
          properties: {
            timeColor: {
              type: "string",
              title: "Time Color"
            },
            dateColor: {
              type: "string",
              title: "Date Color"
            },
            dayColor: {
              type: "string",
              title: "Day Color"
            },
            monthColor: {
              type: "string",
              title: "Month Color"
            }
          },
          required: ["timeColor", "dateColor", "dayColor", "monthColor"]
        },
        visibility: {
          type: "object",
          properties: {
            showTime: {
              type: "boolean",
              title: "Show Time"
            },
            showDate: {
              type: "boolean",
              title: "Show Date"
            },
            showDay: {
              type: "boolean",
              title: "Show Day"
            },
            showMonth: {
              type: "boolean",
              title: "Show Month"
            }
          }
        }
      },
      requiredProperties: [],
      uiSchemaProperties: {},
      getFormValuesByNode: (node: DynamicLayoutNode) => {
        const nodeProps = node.nodeConfig as ClockNodeProps;
        return {
          colors: {
            timeColor: nodeProps?.colors?.timeColor ?? "#FF5733",
            dateColor: nodeProps?.colors?.dateColor ?? "#33FF57",
            dayColor: nodeProps?.colors?.dayColor ?? "#3357FF",
            monthColor: nodeProps?.colors?.monthColor ?? "#FF33A1"
          },
          visibility: {
            showTime: nodeProps?.visibility?.showTime ?? true,
            showDate: nodeProps?.visibility?.showDate ?? true,
            showDay: nodeProps?.visibility?.showDay ?? true,
            showMonth: nodeProps?.visibility?.showMonth ?? true
          }
        };
      },
      setToNode: (node: DynamicLayoutNode, values: any) => {
        node.nodeConfig.colors = values.colors;
        node.nodeConfig.visibility = values.visibility;
      }
    };
  };

  export const SCHEMA_PARTS: SchemaPartsGenerator = (context) => [
    hasClockNodeSchema
  ];

  export const ClockNodeInfo: DynamicLayoutNodeInfo = {
    nodeType: "clock",
    schemaParts: SCHEMA_PARTS,
    iconComponent: Clock
  };
</script>

<script lang="ts">
  import { onMount } from "svelte";
  import { type ComponentProps } from "$lib/components/composites/dynamic-layout";

  let {
    layoutContext
  }: ComponentProps = $props();

  let node = $derived(layoutContext.node);
  let nodeProps = $derived(node.nodeConfig as ClockNodeProps);

  let colors = $derived(nodeProps?.colors ?? {
    timeColor: "#FF5733",
    dateColor: "#33FF57",
    dayColor: "#3357FF",
    monthColor: "#FF33A1"
  });

  let visibility = $derived(nodeProps?.visibility ?? {
    showTime: true,
    showDate: true,
    showDay: true,
    showMonth: true
  });

  let currentTime = $state(new Date());

  onMount(() => {
    const interval = setInterval(() => {
      currentTime = new Date();
    }, 1000);
    return () => clearInterval(interval);
  });

  function formatTime(date: Date) {
    return date.toLocaleTimeString();
  }

  function formatDate(date: Date) {
    return date.toLocaleDateString();
  }

  function formatDay(date: Date) {
    return date.toLocaleString('default', { weekday: 'long' });
  }

  function formatMonth(date: Date) {
    return date.toLocaleString('default', { month: 'long' });
  }
</script>

<style>
  .clock-node {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 1rem;
    border: 1px solid #ddd;
    border-radius: 0.5rem;
    box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
  }

  .time {
    font-size: 2rem;
    color: var(--time-color);
  }

  .date {
    font-size: 1.5rem;
    color: var(--date-color);
  }

  .day {
    font-size: 1.5rem;
    color: var(--day-color);
  }

  .month {
    font-size: 1.5rem;
    color: var(--month-color);
  }
</style>

<div class="clock-node">
  {#if visibility.showTime}
    <div class="time" style="--time-color: {colors.timeColor};">
      {formatTime(currentTime)}
    </div>
  {/if}
  {#if visibility.showDate}
    <div class="date" style="--date-color: {colors.dateColor};">
      {formatDate(currentTime)}
    </div>
  {/if}
  {#if visibility.showDay}
    <div class="day" style="--day-color: {colors.dayColor};">
      {formatDay(currentTime)}
    </div>
  {/if}
  {#if visibility.showMonth}
    <div class="month" style="--month-color: {colors.monthColor};">
      {formatMonth(currentTime)}
    </div>
  {/if}
</div>
