<script lang="ts">
  import {
    type ComponentProps,
    LayoutContext,
    type RenderChildNodeSnippet
  } from "$lib/components/composites/dynamic-layout";
  import type {
    DashboardLayoutNode,
    DynamicLayoutNode
  } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { merge } from "lodash";
  import {
    getPlaceholderPathsFromObject,
    replacePlaceholdersRecursivelyAsync
  } from "$lib/blocks/data-utils/placeholderMethods";
  import DebugDetails from "$lib/components/composites/debug-details/DebugDetails.svelte";
  import { Inspect } from "svelte-inspect-value";
  import type { PayloadContext } from "./dynamic_node_types";
  import { DynamicPayloadNodeContext } from "./DynamicLayoutContexts";
  import { DataSourceRepository, mapToDataSourceDbEntry } from "$lib/database/dataSourceRepository.svelte.js";
  import type { DataSourceDbEntry } from "$lib/database/datasources";
  import { LiveNodeDataState } from "../../../contexts/liveNodeData.context.svelte.js";


  let {
    layoutContext,
    payloadContext,
    parentNode,
    newRenderChildNode,
    rootRenderChildNode
  }: ComponentProps & {
    payloadContext: PayloadContext,
    parentNode: DynamicLayoutNode,
    newRenderChildNode: RenderChildNodeSnippet
    rootRenderChildNode: RenderChildNodeSnippet
  } = $props();

  // todo extract all placeholder methods / combiners into one file
  // for easier changes / improvements

  // the merged payload is also passed down to the children nodes / template nodes
  function mergePayloadContexts (context: LayoutContext, node: DashboardLayoutNode) {
    const contextPayload = context.sharedAdditionalContext?.payload;
    const nodePayload = $state.snapshot(node.nodeConfig?.___payload);
    const mergedPayload = merge({
      scope: {
        parent: contextPayload?.["scope"]
      }
    }, nodePayload);

    return {
      mergedPayload,
      debugEntries: [
        { key: "Merged Payload", value: mergedPayload },
        { key: "Context Payload", value: contextPayload },
        { key: "Node Payload", value: nodePayload }
      ]
    };
  }

  let dataSourcesRaw = DataSourceRepository.getAllSourcesState();
  let dataSources = $derived(dataSourcesRaw.rows.map(mapToDataSourceDbEntry));

  function extendPayload (
    payload: any,
    dataSources: DataSourceDbEntry[],
    liveData: Record<string, any>,
    neededPaths: string[]
  ) {
    let dataSourcesObj: Record<string, any> | undefined = undefined;

    const allNeededSources = neededPaths.filter((path) => path.includes("sources")).map((path) => {
      const splitByPipe = path.split("|");
      const usedSource = splitByPipe[0].trim();

      return usedSource.split(".")[1];
    });

    // if we only add the really used sources, we can skip a re-render
    if (allNeededSources.length > 0) {
      dataSourcesObj = {};

      for (const source of allNeededSources) {
        if (liveData[source]) {
          dataSourcesObj[source] = liveData[source];
        }

        const foundDataSource = dataSources.find((dataSource) => dataSource.config.short === source);
        if (foundDataSource) {
          dataSourcesObj[source] = JSON.parse(foundDataSource.config.code);
        }
      }
    }

    return {
      ...payload,
      sources: dataSourcesObj,
      extended: {
        is: true
      }
    };
  }

  async function replaceNodePayload (node: DynamicLayoutNode, payload: unknown) {
    const result = await replacePlaceholdersRecursivelyAsync(node, payload);

    return result;
  }

  const childNode = $state.snapshot(layoutContext.node);

  const neededPlaceholderPaths = getPlaceholderPathsFromObject(childNode);

  const payload = $derived(mergePayloadContexts(layoutContext, childNode));

  const extendedPayload = $derived(extendPayload(payload.mergedPayload, dataSources, LiveNodeDataState, neededPlaceholderPaths));

  const replacedNode = $state<{
    usedPayloadPaths: string[];
    payloads: Record<string, any>;
    missingPaths: string[];
    result: DynamicLayoutNode | null;
  }>({
    result: null,
    usedPayloadPaths: [],
    payloads: {},
    missingPaths: []
  });

  $effect(() => {
    replaceNodePayload(childNode, extendedPayload).then((result) => {
      replacedNode.result = result.result;
      replacedNode.usedPayloadPaths = result.usedPayloadPaths;
      replacedNode.payloads = result.payloads;
      replacedNode.missingPaths = result.missingPaths;
    });
  });

</script>

<DebugDetails category="TemplatedLayout/isTemplateChildNodeChild"
              pairs={{"ID": layoutContext.node.id, "IS": "Template Child Node Child", "ContextType": layoutContext.ContextType}}
              entries={[...payload.debugEntries,
                      { "key": "node", value: childNode},]} />

{#if replacedNode.result === null}
  replacing values -- magic happens
{:else}
  <DebugDetails category="TemplatedLayout/replaceValues"
                pairs={{"ID": layoutContext.node.id, "IS": "Replaced Payload Node", "ContextType": layoutContext.ContextType}}

                entries={[{ "key": "node", value: replacedNode}]}
  />


  {@const newLayoutContext = DynamicPayloadNodeContext.FROM(
    layoutContext,
    parentNode,
    replacedNode.result,
    newRenderChildNode,
    payload.mergedPayload
  )}


  {@render rootRenderChildNode(newLayoutContext.subNode(replacedNode.result))}
  <!--   {JSON.stringify(replacedNode.node)}
<br />
<br />
<br />
<br />
-->
{/if}
