import type { JsonSchemaParts } from "../jsonSchemaTypes";
import {
	type DynamicLayoutNode, getLabel, setLabel
} from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";

export const hasTitleSchema = (isRequired: boolean) => (): JsonSchemaParts => {
	return {
		dataTab: 'general',
		schemaProperties: {
			label: {
				type: 'string',
				title: 'Label'
			}
		},
		uiSchemaProperties: {
			label: {
				'ui:options': {
					input: {
						autocomplete: 'off'
					}
				}
			}
		},
		requiredProperties: isRequired ? ['label'] : [],
		getFormValuesByNode: (node: DynamicLayoutNode) => {
			return {
				label: getLabel( node)
			};
		},
		setToNode: (node: DynamicLayoutNode, values: any) => {
			setLabel(node, values.label);

			// console.info('setLabel', values.label, node);
		}
	};
};
