import type { DynamicLayoutNode } from '../dynamic-layout-app-types/dynamic-layout-types';


export interface GridChildNodeOptions {
	col: number;
	row: number;
	colSpan: number;
	rowSpan: number;

	cellStyle?: string;
}

export interface GridChildNodePropsOptions {
	forParent: {
		grid: GridChildNodeOptions;
	};
}

export function getGridNodeOptions(node: DynamicLayoutNode): GridChildNodeOptions {
	const defaultProps = { col: 1, row: 1, colSpan: 1, rowSpan: 1 } as GridChildNodeOptions;

	const foundProps = node?.layoutData?.forParent?.grid as GridChildNodeOptions;

	if (!foundProps || typeof foundProps.col === 'undefined') {
		return defaultProps;
	}

	return foundProps;
}

export function getMaxColRow(children: GridChildNodeOptions[]): { maxCol: number; maxRow: number } {
	let maxCol = Math.max(...children.map((t) => t.col + (t.colSpan - 1)));
	let maxRow = Math.max(...children.map((t) => t.row + (t.rowSpan - 1)));

	return { maxCol, maxRow };
}

export function findNextFreeCellBasedOnNodes(nodes: GridChildNodeOptions[]): GridChildNodeOptions {
	const { maxCol, maxRow } = getMaxColRow(nodes);

	function isCellOccupied(col: number, row: number): boolean {
    return nodes.some((node) => {
      const nodeColEnd = node.col + node.colSpan;
      const nodeRowEnd = node.row + node.rowSpan;

      return col >= node.col && col < nodeColEnd &&
             row >= node.row && row < nodeRowEnd;
    });
  }

	const occupiedCell: GridChildNodeOptions = { col: 1, row: 1, colSpan: 1, rowSpan: 1 };

	for (let row = 1; row <= maxRow; row++) {
		for (let col = 1; col <= maxCol; col++) {
			const cell = `${col}-${row}`;
			if (
				!isCellOccupied(col, row)
			) {
				occupiedCell.col = col;
				occupiedCell.row = row;
				return occupiedCell;
			} else {
				occupiedCell.col = col;
				occupiedCell.row = row;
			}
		}
	}

	if (occupiedCell.col < maxCol) {
		occupiedCell.col++;
	} else if (occupiedCell.col === maxCol) {
		occupiedCell.col = 1;
		occupiedCell.row = maxRow + 1;
	}

	return occupiedCell;
}
